/**
 * Team members and positions of the active business, from the API
 * (/api/v1/staff/ and /api/v1/positions/). Only the owner can use them.
 *
 * Accounts are never deleted: they are deactivated and can be reactivated.
 * A password the owner does not type is generated by the server and sent
 * back once as `temporaryPassword`; it cannot be looked up again.
 */

import { api } from './api';

export type StaffRole = 'admin' | 'accountant' | 'staff';

export const ROLE_LABEL: Record<StaffRole, string> = {
  admin: 'Admin',
  accountant: 'Accountant',
  staff: 'Staff',
};

export const MODULES: Array<{ id: string; label: string }> = [
  { id: 'dashboard', label: 'Dashboard' },
  { id: 'inventory', label: 'Inventory' },
  { id: 'purchases', label: 'Purchases' },
  { id: 'sales', label: 'Sales' },
  { id: 'bike_sales', label: 'Bike sales' },
  { id: 'orders', label: 'Orders' },
  { id: 'finance', label: 'Finance' },
  { id: 'staff', label: 'Staff & payroll' },
  { id: 'reports', label: 'Reports' },
  { id: 'reminders', label: 'Reminders' },
];

export interface StaffMember {
  id: number;
  username: string;
  firstName: string;
  lastName: string;
  name: string;
  email: string;
  phone: string;
  role: StaffRole;
  positionId: number | null;
  positionName: string;
  isActive: boolean;
  mustChangePassword: boolean;
  lastLogin: string | null;
  dateJoined: string;
}

export interface StaffInput {
  firstName: string;
  lastName: string;
  username?: string;
  email: string;
  phone: string;
  role: StaffRole;
  positionId: number | null;
  /** Leave empty to have the server generate a temporary password. */
  password?: string;
}

export interface PositionPermission {
  module: string;
  canView: boolean;
  canCreate: boolean;
  canUpdate: boolean;
  canDelete: boolean;
}

export interface Position {
  id: number;
  name: string;
  description: string;
  department: string;
  isActive: boolean;
  staffCount: number;
  permissions: PositionPermission[];
  /** Every `module.action` code the position grants. */
  granted: string[];
}

export interface PositionInput {
  name: string;
  description: string;
  department?: string;
  isActive?: boolean;
  /** The full list of `module.action` codes the position grants. */
  codes: string[];
  /** On create only: the preset this position started from. */
  preset?: string;
}

export interface CatalogueAction {
  action: string;
  code: string;
  label: string;
  /** Reserved codes belong to the owner and can never be handed out. */
  reserved: boolean;
}

export interface CatalogueModule {
  module: string;
  label: string;
  actions: CatalogueAction[];
}

export interface Preset {
  key: string;
  label: string;
  department: string;
  permissions: string[];
}

export type OverrideEffect = 'inherit' | 'allow' | 'deny';

export interface StaffAccess {
  /** What the position gives. */
  inherited: string[];
  /** The person's own exceptions, by code. */
  overrides: Record<string, 'allow' | 'deny'>;
  /** The result. */
  effective: string[];
  positionId: number | null;
}

interface ApiStaff {
  id: number;
  username: string;
  first_name: string;
  last_name: string;
  email: string;
  phone: string;
  role: StaffRole;
  position: number | null;
  position_name: string | null;
  is_active: boolean;
  must_change_password: boolean;
  last_login: string | null;
  date_joined: string;
  temporary_password?: string;
}

interface ApiPosition {
  id: number;
  name: string;
  description: string;
  department?: string;
  granted?: string[];
  is_active: boolean;
  staff_count: number;
  permissions: Array<{
    module: string;
    can_view: boolean;
    can_create: boolean;
    can_update: boolean;
    can_delete: boolean;
  }>;
}

interface Page<T> {
  next: string | null;
  results: T[];
}

function staffFromApi(s: ApiStaff): StaffMember {
  const name = `${s.first_name} ${s.last_name}`.trim();
  return {
    id: s.id,
    username: s.username,
    firstName: s.first_name,
    lastName: s.last_name,
    name: name || s.username,
    email: s.email,
    phone: s.phone,
    role: s.role,
    positionId: s.position,
    positionName: s.position_name ?? '',
    isActive: s.is_active,
    mustChangePassword: s.must_change_password,
    lastLogin: s.last_login,
    dateJoined: s.date_joined,
  };
}

function positionFromApi(p: ApiPosition): Position {
  return {
    id: p.id,
    name: p.name,
    description: p.description,
    department: p.department ?? '',
    granted: p.granted ?? [],
    isActive: p.is_active,
    staffCount: p.staff_count,
    permissions: p.permissions.map((x) => ({
      module: x.module,
      canView: x.can_view,
      canCreate: x.can_create,
      canUpdate: x.can_update,
      canDelete: x.can_delete,
    })),
  };
}

async function all<T>(path: string): Promise<T[]> {
  const out: T[] = [];
  let page = 1;
  for (;;) {
    const sep = path.includes('?') ? '&' : '?';
    const data = await api<Page<T>>(`${path}${sep}page=${page}&page_size=100`);
    out.push(...data.results);
    if (!data.next) break;
    page += 1;
  }
  return out;
}

// ---------- team ----------

export async function listStaff(): Promise<StaffMember[]> {
  return (await all<ApiStaff>('/staff/')).map(staffFromApi);
}

export async function getStaff(id: number): Promise<StaffMember> {
  return staffFromApi(await api<ApiStaff>(`/staff/${id}/`));
}

export async function createStaff(
  input: StaffInput,
): Promise<{ member: StaffMember; temporaryPassword: string | null }> {
  const body: Record<string, unknown> = {
    username: (input.username ?? '').trim(),
    first_name: input.firstName.trim(),
    last_name: input.lastName.trim(),
    email: input.email.trim(),
    phone: input.phone.trim(),
    role: input.role,
    position: input.role === 'staff' ? input.positionId : null,
  };
  if (input.password) body.password = input.password;

  const data = await api<ApiStaff>('/staff/', { method: 'POST', body });
  return { member: staffFromApi(data), temporaryPassword: data.temporary_password ?? null };
}

export async function updateStaff(id: number, input: StaffInput): Promise<StaffMember> {
  const data = await api<ApiStaff>(`/staff/${id}/`, {
    method: 'PATCH',
    body: {
      first_name: input.firstName.trim(),
      last_name: input.lastName.trim(),
      email: input.email.trim(),
      phone: input.phone.trim(),
      role: input.role,
      position: input.role === 'staff' ? input.positionId : null,
    },
  });
  return staffFromApi(data);
}

export async function deactivateStaff(id: number): Promise<void> {
  await api(`/staff/${id}/`, { method: 'DELETE' });
}

export async function reactivateStaff(id: number): Promise<StaffMember> {
  return staffFromApi(await api<ApiStaff>(`/staff/${id}/reactivate/`, { method: 'POST', body: {} }));
}

/** Sets a new temporary password (generated unless one is given); returns it when generated. */
export async function resetStaffPassword(id: number, password?: string): Promise<string | null> {
  const data = await api<{ temporary_password?: string }>(`/staff/${id}/reset-password/`, {
    method: 'POST',
    body: password ? { password } : {},
  });
  return data.temporary_password ?? null;
}

// ---------- positions ----------

export async function listPositions(): Promise<Position[]> {
  return (await all<ApiPosition>('/positions/')).map(positionFromApi);
}

function positionBody(input: PositionInput): Record<string, unknown> {
  const body: Record<string, unknown> = {
    name: input.name.trim(),
    description: input.description.trim(),
    // The full list, so unticked boxes are really switched off.
    codes: input.codes,
  };
  if (input.department !== undefined) body.department = input.department.trim();
  if (input.preset) body.preset = input.preset;
  if (input.isActive !== undefined) body.is_active = input.isActive;
  return body;
}

export async function createPosition(input: PositionInput): Promise<Position> {
  return positionFromApi(await api<ApiPosition>('/positions/', { method: 'POST', body: positionBody(input) }));
}

export async function updatePosition(id: number, input: PositionInput): Promise<Position> {
  return positionFromApi(
    await api<ApiPosition>(`/positions/${id}/`, { method: 'PATCH', body: positionBody(input) }),
  );
}

export async function setPositionActive(id: number, isActive: boolean): Promise<Position> {
  return positionFromApi(
    await api<ApiPosition>(`/positions/${id}/`, { method: 'PATCH', body: { is_active: isActive } }),
  );
}

/** A position in use cannot be deleted; the API answers 409 with the reason. */
export async function deletePosition(id: number): Promise<void> {
  await api(`/positions/${id}/`, { method: 'DELETE' });
}

// ---------- permissions ----------

/** Every module and action a position can grant (what the API understands). */
export async function loadCatalogue(): Promise<CatalogueModule[]> {
  return api<CatalogueModule[]>('/positions/catalogue/');
}

/** Starting templates for a new position. Picking one only copies its grants. */
export async function loadPresets(): Promise<Preset[]> {
  return api<Preset[]>('/positions/presets/');
}

interface ApiAccess {
  inherited: string[];
  overrides: Record<string, 'allow' | 'deny'>;
  effective: string[];
  position: number | null;
}

function accessFromApi(a: ApiAccess): StaffAccess {
  return {
    inherited: a.inherited,
    overrides: a.overrides,
    effective: a.effective,
    positionId: a.position,
  };
}

export async function getAccess(id: number): Promise<StaffAccess> {
  return accessFromApi(await api<ApiAccess>(`/staff/${id}/access/`));
}

/** Owner only. Sets, changes or clears one person's own exceptions. */
export async function saveOverrides(
  id: number,
  changes: Array<{ permission: string; effect: OverrideEffect }>,
): Promise<StaffAccess> {
  return accessFromApi(
    await api<ApiAccess>(`/staff/${id}/access/`, { method: 'PUT', body: { overrides: changes } }),
  );
}
